INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(166890, 9506, 3080, '<td valign="top">Interesting.  Dark, but I assume you did that on purpose.  The angle and framing/cropping you have chosen is nice.  I really like the curves in the waterline.  The darkness does make it a bit difficult to get a lot of detail, however, still a nice shot.  Good luck in the challenge.</td>', 'Interesting.  Dark, but I assume you did that on purpose.  The angle and framing/cropping you have chosen is nice.  I really like the curves in the waterline.  The darkness does make it a bit difficult to get a lot of detail, however, still a nice shot.  Good luck in the challenge.', '2002-12-09 00:10:55.000000', NULL, 1),
(166891, 9383, 3080, '<td valign="top">Nice use of DOF.  I like the nicely focused mouthpiece, and the soft focus body.  The extra added color is nice as well.  Looks like you took the shot near your christmas tree. :)  The very top edge of the mouthpiece looks a tad strange.  not sure if it''s a reflection, or something that happened in post processing.  angle and framing/cropping are great. good luck in the challenge.</td>', 'Nice use of DOF.  I like the nicely focused mouthpiece, and the soft focus body.  The extra added color is nice as well.  Looks like you took the shot near your christmas tree. :)  The very top edge of the mouthpiece looks a tad strange.  not sure if it''s a reflection, or something that happened in post processing.  angle and framing/cropping are great. good luck in the challenge.', '2002-12-09 00:13:01.000000', NULL, 1),
(166896, 9586, 3080, '<td valign="top">The shot is interesting.  I assume it''s an ice covered branch.  The background is nice, not distracting at all.  the focus and clarity seem very well done.  lighting is good as well.  seems to be lacking something to really give it "wow" for me though.  still technically very well done. good luck in the challenge.</td>', 'The shot is interesting.  I assume it''s an ice covered branch.  The background is nice, not distracting at all.  the focus and clarity seem very well done.  lighting is good as well.  seems to be lacking something to really give it "wow" for me though.  still technically very well done. good luck in the challenge.', '2002-12-09 00:14:25.000000', NULL, 1),
(166898, 9402, 312, '<td valign="top">fantastic.</td>', 'fantastic.', '2002-12-09 00:15:03.000000', NULL, 1),
(166900, 9568, 3080, '<td valign="top">I like how you got the angels wings, and the bird in the shot. what wonderful timing.  the statue is interesting looking.  I wish we could get a bit more detail, but probably difficult to get detail and the nice effect from the sun.  the angle and framig/cropping are ok.  maybe just a bit much room to the right.  it looks like she is facing to the left, which automatically tells my brain that I wish there were more space to the left of the photo, than to the right.  otherwise a nice shot.  good luck in the challenge.</td>', 'I like how you got the angels wings, and the bird in the shot. what wonderful timing.  the statue is interesting looking.  I wish we could get a bit more detail, but probably difficult to get detail and the nice effect from the sun.  the angle and framig/cropping are ok.  maybe just a bit much room to the right.  it looks like she is facing to the left, which automatically tells my brain that I wish there were more space to the left of the photo, than to the right.  otherwise a nice shot.  good luck in the challenge.', '2002-12-09 00:16:56.000000', NULL, 1),
(166906, 9402, 2361, '<td valign="top">Very interesting idea.</td>', 'Very interesting idea.', '2002-12-09 00:18:59.000000', NULL, 1),
(166908, 9473, 3080, '<td valign="top">The spot that seems to be in the best focus is the spot right below dead center of the photo.  where the blue and purple stockings meet.  That isn''t really the most interesting part of the photo.  I think I''d like to see more of the photo in focus.  and with a different background.  a very nice idea, but I think it lacks that something so make is scream ''wow'' to me.  I wonder how this would look with the red stocking in the middle seperating the 2 "similar" looking colors.  I think that would make it more interesting.  Otherwise though a nice shot.  good luck in the challenge.</td>', 'The spot that seems to be in the best focus is the spot right below dead center of the photo.  where the blue and purple stockings meet.  That isn''t really the most interesting part of the photo.  I think I''d like to see more of the photo in focus.  and with a different background.  a very nice idea, but I think it lacks that something so make is scream ''wow'' to me.  I wonder how this would look with the red stocking in the middle seperating the 2 "similar" looking colors.  I think that would make it more interesting.  Otherwise though a nice shot.  good luck in the challenge.', '2002-12-09 00:19:50.000000', NULL, 1),
(166913, 9378, 3080, '<td valign="top">Very interesting subject.  the colors are very nice, as are the patterns.  The angle and framing/cropping you have chosen is good as well.  I really like the tiny photo.  isn''t it nice to not have the size limitation?  The little sun star under the marble to the bottom right is nice.  focus is good as well.  nice shot. good luck in the challenge.</td>', 'Very interesting subject.  the colors are very nice, as are the patterns.  The angle and framing/cropping you have chosen is good as well.  I really like the tiny photo.  isn''t it nice to not have the size limitation?  The little sun star under the marble to the bottom right is nice.  focus is good as well.  nice shot. good luck in the challenge.', '2002-12-09 00:21:32.000000', NULL, 1),
(166914, 9396, 2361, '<td valign="top">I like this very much; it is well conceived and well- executed</td>', 'I like this very much; it is well conceived and well- executed', '2002-12-09 00:21:43.000000', NULL, 1),
(166921, 9494, 3080, '<td valign="top">wow.  This is a very busy photo, however, very nicely organized.  the patterns are great!!  curved and pointy, round and square.  very lovely.  I like the use of black and white here.  I think without the color, it turns it from busy, to artistic.  I''m not so sure about the guy though.  his shirt is very bright, and I think it might be just bright enough to draw the eyes away from the patterns in the goods.  overall very very nice.  Good luck in the challenge.</td>', 'wow.  This is a very busy photo, however, very nicely organized.  the patterns are great!!  curved and pointy, round and square.  very lovely.  I like the use of black and white here.  I think without the color, it turns it from busy, to artistic.  I''m not so sure about the guy though.  his shirt is very bright, and I think it might be just bright enough to draw the eyes away from the patterns in the goods.  overall very very nice.  Good luck in the challenge.', '2002-12-09 00:23:59.000000', NULL, 1),
(166924, 9452, 2361, '<td valign="top">Very clean lines.  Good capture.</td>', 'Very clean lines.  Good capture.', '2002-12-09 00:24:16.000000', NULL, 1),
(166929, 9552, 2361, '<td valign="top">This is a beautiful balance of tones. Well done.</td>', 'This is a beautiful balance of tones. Well done.', '2002-12-09 00:25:45.000000', NULL, 1),
(166930, 9526, 3080, '<td valign="top">Great title.  not that that matters a whole lot, but it is quite catchy.  I really like the canoes.  That red is very red.  I like the combination of the 3 canoes.  Your focus and clarity are great, and the angle and framing/cropping are great as well.  You have done an excelent job with this shot. Good luck in the challenge.</td>', 'Great title.  not that that matters a whole lot, but it is quite catchy.  I really like the canoes.  That red is very red.  I like the combination of the 3 canoes.  Your focus and clarity are great, and the angle and framing/cropping are great as well.  You have done an excelent job with this shot. Good luck in the challenge.', '2002-12-09 00:25:46.000000', NULL, 1),
(166931, 9575, 806, '<td valign="top">I know the rules state that you can submit a photo of this size, but I really wish people would use that for panorama''s and such. It is really difficult to give you the full benefit of a proper critique and vote on an image of this size, where I cannot discern details... and I have a 19 inch monitor. I can imagine what people with smaller monitors are thinking...<br/> <br/>Now... it seems like a very interesting subject. I would like it to be flipped horizontally, imho, so that my eye is led off the fork with the snail, as the motion is going in that direction.</td>', 'I know the rules state that you can submit a photo of this size, but I really wish people would use that for panorama''s and such. It is really difficult to give you the full benefit of a proper critique and vote on an image of this size, where I cannot discern details... and I have a 19 inch monitor. I can imagine what people with smaller monitors are thinking... Now... it seems like a very interesting subject. I would like it to be flipped horizontally, imho, so that my eye is led off the fork with the snail, as the motion is going in that direction.', '2002-12-09 00:26:02.000000', NULL, 1),
(166939, 9494, 2361, '<td valign="top">I''m rather surprised at the B&amp;W choice (but then again, I tend towards very colourful images).  Were the colours distracting?</td>', 'I''m rather surprised at the B&W choice (but then again, I tend towards very colourful images).  Were the colours distracting?', '2002-12-09 00:28:49.000000', NULL, 1),
(166940, 9469, 2279, '<td valign="top">It looks a little crooked to me. But besides that its a really neat shot.</td>', 'It looks a little crooked to me. But besides that its a really neat shot.', '2002-12-09 00:29:40.000000', NULL, 1),
(166941, 9503, 2003, '<td valign="top">i feel your pain 7</td>', 'i feel your pain 7', '2002-12-09 00:30:38.000000', NULL, 1),
(166943, 9482, 806, '<td valign="top">gorgeous!!! nice work,...and nice spin on this subject!</td>', 'gorgeous!!! nice work,...and nice spin on this subject!', '2002-12-09 00:30:48.000000', NULL, 1),
(166944, 9575, 772, '<td valign="top">This is potentially a very good photo... I would highly recommend choosing a larger size in the future so details can be viewed.  Detail is important in a shot like this, and at this size, it can''t be seen.... - setzler</td>', 'This is potentially a very good photo... I would highly recommend choosing a larger size in the future so details can be viewed.  Detail is important in a shot like this, and at this size, it can''t be seen.... - setzler', '2002-12-09 00:31:10.000000', NULL, 1),
(166946, 9369, 806, '<td valign="top">very creative!</td>', 'very creative!', '2002-12-09 00:31:51.000000', NULL, 1),
(166950, 9313, 2361, '<td valign="top">I would have liked to have have seen the back end of the socket line up with the black/white divider in the same way as does the front end.  An interesting macro that suggests a number of further possibilities.</td>', 'I would have liked to have have seen the back end of the socket line up with the black/white divider in the same way as does the front end.  An interesting macro that suggests a number of further possibilities.', '2002-12-09 00:32:18.000000', NULL, 1),
(166952, 9578, 806, '<td valign="top">excellent detail... good choice of dof.</td>', 'excellent detail... good choice of dof.', '2002-12-09 00:33:23.000000', NULL, 1),
(166959, 9310, 806, '<td valign="top">LOL! very funny!</td>', 'LOL! very funny!', '2002-12-09 00:35:39.000000', NULL, 1),
(166960, 9531, 806, '<td valign="top">not sure the choice of such a wide border adds to the photo. image quality is not so good, but I like the play of the reflections with the geometry.</td>', 'not sure the choice of such a wide border adds to the photo. image quality is not so good, but I like the play of the reflections with the geometry.', '2002-12-09 00:36:44.000000', NULL, 1),
(166980, 9482, 2361, '<td valign="top">Very pleasing effect.</td>', 'Very pleasing effect.', '2002-12-09 00:44:28.000000', NULL, 1),
(166984, 9567, 2279, '<td valign="top">Wow! thats a really neat sunrise. Good job. The only thing I would change is maybe cropping out some of the top and just make it a thinner picture.</td>', 'Wow! thats a really neat sunrise. Good job. The only thing I would change is maybe cropping out some of the top and just make it a thinner picture.', '2002-12-09 00:46:35.000000', NULL, 1),
(166989, 9501, 2279, '<td valign="top">I like this shot but I wish the entire branch was in focus.</td>', 'I like this shot but I wish the entire branch was in focus.', '2002-12-09 00:49:14.000000', NULL, 1),
(166992, 9450, 5212, '<td valign="top">One of my favorites, gave it a ten</td>', 'One of my favorites, gave it a ten', '2002-12-09 00:49:42.000000', NULL, 1),
(166994, 9552, 5212, '<td valign="top">Nice use of color and light</td>', 'Nice use of color and light', '2002-12-09 00:50:43.000000', NULL, 1),
(166995, 9367, 2279, '<td valign="top">Wow! I really like the lines in this shot. And the colors are great too.</td>', 'Wow! I really like the lines in this shot. And the colors are great too.', '2002-12-09 00:51:29.000000', NULL, 1),
(166997, 9447, 2279, '<td valign="top">Very nice composition but it seems just a little too dark for me.</td>', 'Very nice composition but it seems just a little too dark for me.', '2002-12-09 00:52:32.000000', NULL, 1),
(166999, 9546, 5212, '<td valign="top">Not wild abot the buildings in the background, but still a nice photo</td>', 'Not wild abot the buildings in the background, but still a nice photo', '2002-12-09 00:52:52.000000', NULL, 1),
(167004, 9495, 2279, '<td valign="top">I like the colors but the picture looks crooked to me.</td>', 'I like the colors but the picture looks crooked to me.', '2002-12-09 00:54:25.000000', NULL, 1),
(167005, 9491, 5212, '<td valign="top">Great portrait!</td>', 'Great portrait!', '2002-12-09 00:54:25.000000', NULL, 1),
(167008, 9336, 5212, '<td valign="top">Wow, what a use of color and special effects!!</td>', 'Wow, what a use of color and special effects!!', '2002-12-09 00:55:10.000000', NULL, 1),
(167012, 9459, 2279, '<td valign="top">It looks a little bit blurry but great composition. I like how they are just entering the photo.</td>', 'It looks a little bit blurry but great composition. I like how they are just entering the photo.', '2002-12-09 00:55:42.000000', NULL, 1),
(167013, 9494, 3936, '<td valign="top">While I like B&amp;W photos, I really wish this one could have been in color.  Looking at it I can only imagine the riot of color that must have been present. 7</td>', 'While I like B&W photos, I really wish this one could have been in color.  Looking at it I can only imagine the riot of color that must have been present. 7', '2002-12-09 00:55:54.000000', NULL, 1),
(167017, 9561, 573, '<td valign="top">In my experence BB''s are copper colored, so you applied some heavy color manipulstion, right?</td>', 'In my experence BB''s are copper colored, so you applied some heavy color manipulstion, right?', '2002-12-09 00:57:36.000000', NULL, 1),
(167020, 9506, 2279, '<td valign="top">I think this shot would have been better if it was a lot lighter.</td>', 'I think this shot would have been better if it was a lot lighter.', '2002-12-09 00:59:09.000000', NULL, 1),
(167021, 9583, 5212, '<td valign="top">Nice use of framing to enhance this shot.</td>', 'Nice use of framing to enhance this shot.', '2002-12-09 00:59:51.000000', NULL, 1),
(167022, 9551, 3080, '<td valign="top">What great depth!  Interesting shot definately.  I like the round patterns mixed with the flat patterns of the stairs, and the square pattern of the wire around the stairs. focus is very good throughout the shot.  what an interesting find. good luck in the challenge.</td>', 'What great depth!  Interesting shot definately.  I like the round patterns mixed with the flat patterns of the stairs, and the square pattern of the wire around the stairs. focus is very good throughout the shot.  what an interesting find. good luck in the challenge.', '2002-12-09 01:00:08.000000', NULL, 1),
(167026, 9433, 3080, '<td valign="top">what a wonderful shot!!  I really like this one a lot.  The angle and framing/cropping are great!  I really love the lighthouse against the blue sky and the clouds are beautiful.  Your focus and clarity are supurb!  What an excelent job you have done with this.  I could hang it on my wall for sure.  Good luck in the challenge.</td>', 'what a wonderful shot!!  I really like this one a lot.  The angle and framing/cropping are great!  I really love the lighthouse against the blue sky and the clouds are beautiful.  Your focus and clarity are supurb!  What an excelent job you have done with this.  I could hang it on my wall for sure.  Good luck in the challenge.', '2002-12-09 01:01:21.000000', NULL, 1),
(167027, 9340, 573, '<td valign="top">Normaly I frown on the photographers image captured in the picture, but this is an exception.</td>', 'Normaly I frown on the photographers image captured in the picture, but this is an exception.', '2002-12-09 01:02:56.000000', NULL, 1),
(167028, 9538, 3080, '<td valign="top">Beautiful!  You have done a great job with the lighting on this. Nothing too bright, nothing too dark.  I love your focus and clarity.  You give us great detail in this shot.  I had the pleasure of playing french horn (among lots of other instruments) and enjoy seeing photos of instruments.  angle and framing/cropping are great.  I like how the subject fills the entire photo.  Great job. Good luck in the challenge.</td>', 'Beautiful!  You have done a great job with the lighting on this. Nothing too bright, nothing too dark.  I love your focus and clarity.  You give us great detail in this shot.  I had the pleasure of playing french horn (among lots of other instruments) and enjoy seeing photos of instruments.  angle and framing/cropping are great.  I like how the subject fills the entire photo.  Great job. Good luck in the challenge.', '2002-12-09 01:03:17.000000', NULL, 1),
(167029, 9585, 5212, '<td valign="top">The background to the left distracts me a bit for some reason.</td>', 'The background to the left distracts me a bit for some reason.', '2002-12-09 01:05:16.000000', NULL, 1),
(167030, 9378, 5212, '<td valign="top">Nice macro</td>', 'Nice macro', '2002-12-09 01:05:49.000000', NULL, 1),
(167032, 9571, 3080, '<td valign="top">What lovely color.  The lighting is just right on this to bring out a lot of color.  ALMOST a bit bright on the whites, however not bad at all.  I really like how you have filled the entire photo with the subject.  Great angle and framing/cropping. focus is also well done.  Great shot. Good luck in the challenge.</td>', 'What lovely color.  The lighting is just right on this to bring out a lot of color.  ALMOST a bit bright on the whites, however not bad at all.  I really like how you have filled the entire photo with the subject.  Great angle and framing/cropping. focus is also well done.  Great shot. Good luck in the challenge.', '2002-12-09 01:05:57.000000', NULL, 1),
(167034, 9417, 3080, '<td valign="top">Wonderful, what can I say?  Focus and clarity are awesome.  background is nice, not distracting at all.  The pose is great. border goes very well with the photo.  angle and framing/cropping are perfect in my opinion.  If this were my dog, I would have paid to have this taken.  Great great job!!  Good luck in the challenge.</td>', 'Wonderful, what can I say?  Focus and clarity are awesome.  background is nice, not distracting at all.  The pose is great. border goes very well with the photo.  angle and framing/cropping are perfect in my opinion.  If this were my dog, I would have paid to have this taken.  Great great job!!  Good luck in the challenge.', '2002-12-09 01:07:03.000000', NULL, 1),
(167036, 9543, 5212, '<td valign="top">Loved this, gave it a 10</td>', 'Loved this, gave it a 10', '2002-12-09 01:07:37.000000', NULL, 1),
(167037, 9482, 2279, '<td valign="top">Woo...this is a neat one. Ive seen this idea a million times but not like this. This ones gonna be near the top. The only thing I dont like is how dark the reflection of the faucet is.</td>', 'Woo...this is a neat one. Ive seen this idea a million times but not like this. This ones gonna be near the top. The only thing I dont like is how dark the reflection of the faucet is.', '2002-12-09 01:08:02.000000', NULL, 1),
(167041, 9482, 3936, '<td valign="top">Just when you think that water drop photos are old hat, a dime a dozen, along comes one that makes you sit and stare.  Amazing!  Wow!  Beautiful!  The color, the lighting, the contrast, the focus, wow!  10-10-10!  Wish it could go higher.</td>', 'Just when you think that water drop photos are old hat, a dime a dozen, along comes one that makes you sit and stare.  Amazing!  Wow!  Beautiful!  The color, the lighting, the contrast, the focus, wow!  10-10-10!  Wish it could go higher.', '2002-12-09 01:08:47.000000', NULL, 1),
(167064, 9568, 5212, '<td valign="top">I would have liked to see about a third of the right side cropped out.  Otherwise, very nice photo.</td>', 'I would have liked to see about a third of the right side cropped out.  Otherwise, very nice photo.', '2002-12-09 01:24:27.000000', NULL, 1),
(167065, 9559, 5212, '<td valign="top">Wish the bird was a little more in focus.  Look like it had a little more saturation than needed??</td>', 'Wish the bird was a little more in focus.  Look like it had a little more saturation than needed??', '2002-12-09 01:25:42.000000', NULL, 1),
(167067, 9485, 5212, '<td valign="top">LIke the repeating shapes.</td>', 'LIke the repeating shapes.', '2002-12-09 01:26:34.000000', NULL, 1),
(167068, 9315, 5212, '<td valign="top">Nice photo, gave it an 8</td>', 'Nice photo, gave it an 8', '2002-12-09 01:27:18.000000', NULL, 1),
