(167074, 9538, 5475, '<td valign="top">Great composition and lighting! Nice detail and DOF also.  9.0<br/>smellyfish1002</td>', 'Great composition and lighting! Nice detail and DOF also.  9.0smellyfish1002', '2002-12-09 01:31:45.000000', NULL, 1),
(167076, 9388, 5475, '<td valign="top">This looks kind of boring until you open the image.  The lighting and detials are great.  the thumbnail doesn''t so it justice!</td>', 'This looks kind of boring until you open the image.  The lighting and detials are great.  the thumbnail doesn''t so it justice!', '2002-12-09 01:32:46.000000', NULL, 1),
(167077, 9313, 5475, '<td valign="top">Nice composition.  You did a great job of creating an appealing photo of a simple (and not very appealing) object!  7.0<br/>smellyfish1002</td>', 'Nice composition.  You did a great job of creating an appealing photo of a simple (and not very appealing) object!  7.0smellyfish1002', '2002-12-09 01:33:50.000000', NULL, 1),
