(167966, 9450, 2170, '<td valign="top">Lovely perspective.  Softer light and perhaps a longer exposure would tone down that blast on the left.  Well done.</td>', 'Lovely perspective.  Softer light and perhaps a longer exposure would tone down that blast on the left.  Well done.', '2002-12-09 15:09:03.000000', NULL, 1),
(167968, 9313, 2170, '<td valign="top">Nice geometric patterns.  Very interesting image to boot.</td>', 'Nice geometric patterns.  Very interesting image to boot.', '2002-12-09 15:09:55.000000', NULL, 1),
(167971, 9550, 2170, '<td valign="top">Great patterns and focus.  Love the amount of detail in this image.</td>', 'Great patterns and focus.  Love the amount of detail in this image.', '2002-12-09 15:11:25.000000', NULL, 1),
(167972, 9494, 2170, '<td valign="top">It looks like this image was resized pretty poorly....  All of the detail is lost in jaggedy edges where there should be clean lines.  This is a great image, though.</td>', 'It looks like this image was resized pretty poorly....  All of the detail is lost in jaggedy edges where there should be clean lines.  This is a great image, though.', '2002-12-09 15:12:28.000000', NULL, 1),
(167973, 9482, 2011, '<td valign="top">And the winner is. Congrats on catching this perfect shot.10</td>', 'And the winner is. Congrats on catching this perfect shot.10', '2002-12-09 15:12:32.000000', NULL, 1),
(167975, 9386, 2170, '<td valign="top">Excellent image, but the color seems quite washed out.</td>', 'Excellent image, but the color seems quite washed out.', '2002-12-09 15:13:42.000000', NULL, 1),
