(168474, 9531, 4625, '<td valign="top">A bit grainy... Nice concept though, would have loved to see this crisp and clear.</td>', 'A bit grainy... Nice concept though, would have loved to see this crisp and clear.', '2002-12-09 21:36:46.000000', NULL, 1),
(168476, 9503, 4162, '<td valign="top">I know that feeling!</td>', 'I know that feeling!', '2002-12-09 21:37:23.000000', NULL, 1),
