(169267, 9566, 1826, '<td valign="top">You''ve really captured her energy here. Nice work.</td>', 'You''ve really captured her energy here. Nice work.', '2002-12-10 13:51:39.000000', NULL, 1),
(169268, 9383, 3459, '<td valign="top">Interesting composition, personally for my taste I would have used a very deep DOF to keep the whole subject in focus; but you probbaly did the oposit on purpose (which works great too).  Just a difference in taste; great job.</td>', 'Interesting composition, personally for my taste I would have used a very deep DOF to keep the whole subject in focus; but you probbaly did the oposit on purpose (which works great too).  Just a difference in taste; great job.', '2002-12-10 13:51:46.000000', NULL, 1),
(169270, 9582, 3459, '<td valign="top">A very "Hallmark" image (it''s a complement).  I like the gradation of the red on the ball, however the reflection (the yellow spot) spoils it a bit for me.  Great composition, good effort.</td>', 'A very "Hallmark" image (it''s a complement).  I like the gradation of the red on the ball, however the reflection (the yellow spot) spoils it a bit for me.  Great composition, good effort.', '2002-12-10 13:53:09.000000', NULL, 1),
