(170302, 9367, 4055, '<td valign="top">I like it. Interesting because I can´t say exactly what it is. Perhaps some Christmas-things hanging from a roof? Never mind - it´s a good composition, maybe a little tight framed up and right. I would like a little more air round the black circle. (But I´m not THAT sure.) Overall a great shot. (7)</td>', 'I like it. Interesting because I can´t say exactly what it is. Perhaps some Christmas-things hanging from a roof? Never mind - it´s a good composition, maybe a little tight framed up and right. I would like a little more air round the black circle. (But I´m not THAT sure.) Overall a great shot. (7)', '2002-12-11 13:16:34.000000', NULL, 1),
(170303, 9345, 749, '<td valign="top">The textures on this are superb, as are the colours. My only complaint would be that the focus doesn''t feel quite right, but that may be due to a limitation of the camera.</td>', 'The textures on this are superb, as are the colours. My only complaint would be that the focus doesn''t feel quite right, but that may be due to a limitation of the camera.', '2002-12-11 13:19:18.000000', NULL, 1),
(170305, 9396, 472, '<td valign="top">this is great. not cliched at all. love it.</td>', 'this is great. not cliched at all. love it.', '2002-12-11 13:20:18.000000', NULL, 1),
(170307, 9568, 749, '<td valign="top">Interesting use of the sun to create a silhouette, and the bird (pigeon?) in flight is a nice catch. However, due to the silhouetting and the angle, the wings on the statue dont make it immediately clear what it is - a few paces to the right would mean that the left wing didnt go throught the statue''s head, and it would still be silhouetted against the sun. The focus on the background feels a bit off - I''d prefer it if the DoF was either a bit deeper with everything in focus, or a bit shallower, with the background trees more out of focus.</td>', 'Interesting use of the sun to create a silhouette, and the bird (pigeon?) in flight is a nice catch. However, due to the silhouetting and the angle, the wings on the statue dont make it immediately clear what it is - a few paces to the right would mean that the left wing didnt go throught the statue''s head, and it would still be silhouetted against the sun. The focus on the background feels a bit off - I''d prefer it if the DoF was either a bit deeper with everything in focus, or a bit shallower, with the background trees more out of focus.', '2002-12-11 13:23:43.000000', NULL, 1),
(170308, 9510, 4055, '<td valign="top">This is a lovely portrait of a lovely child. Sharp with perfect lighting. It´s just the background - it´s a bit disturbing because it is so light. If it was allowed Photoshop could do marvelous job here. Overall a nice photo to look at.</td>', 'This is a lovely portrait of a lovely child. Sharp with perfect lighting. It´s just the background - it´s a bit disturbing because it is so light. If it was allowed Photoshop could do marvelous job here. Overall a nice photo to look at.', '2002-12-11 13:25:31.000000', NULL, 1),
(170313, 9417, 4055, '<td valign="top">Almost a perfect photo of a lovely dog. But I´m not so sure about the border colour. It takes away my eyes from the dog. A smaller border in a brown colour would probably do it.</td>', 'Almost a perfect photo of a lovely dog. But I´m not so sure about the border colour. It takes away my eyes from the dog. A smaller border in a brown colour would probably do it.', '2002-12-11 13:37:30.000000', NULL, 1),
(170314, 9469, 749, '<td valign="top">Interesting perspective shot this, its just unlucky that it doesn''t line up perfectly square, and that lefthand side railing is a bit distracting, but there''s not much you can do about either of thoset :o) The blues of this shot really add to the sense of this being frozen - this shot may work well as a blue-based mono/duotone.</td>', 'Interesting perspective shot this, its just unlucky that it doesn''t line up perfectly square, and that lefthand side railing is a bit distracting, but there''s not much you can do about either of thoset :o) The blues of this shot really add to the sense of this being frozen - this shot may work well as a blue-based mono/duotone.', '2002-12-11 13:43:40.000000', NULL, 1),
(170318, 9439, 749, '<td valign="top">The mottled-effect of the light coming in (presumably through tree branches) is great, and the blinds are at the right angle too. However, having the chair in shot detracts from the overall image, plus it hides some of the wall being lit, which is a pity.</td>', 'The mottled-effect of the light coming in (presumably through tree branches) is great, and the blinds are at the right angle too. However, having the chair in shot detracts from the overall image, plus it hides some of the wall being lit, which is a pity.', '2002-12-11 13:48:46.000000', NULL, 1),
(170321, 9482, 749, '<td valign="top">Great stopped motion shot this (you could have entered it in both challenges this week ;o). I''m curious as to whether the colours on this are part of the bowl, or whether they are actually in the water itself.</td>', 'Great stopped motion shot this (you could have entered it in both challenges this week ;o). I''m curious as to whether the colours on this are part of the bowl, or whether they are actually in the water itself.', '2002-12-11 13:51:45.000000', NULL, 1),
(170322, 9566, 749, '<td valign="top">Love the expression on this one, nicely timed candid. The positioning of the frame/crop helps add to the fact that she is looking out to the left of the camera. However, it looks as though something like NeatImage has been used, since it feels like the detail in the hair has been lost.</td>', 'Love the expression on this one, nicely timed candid. The positioning of the frame/crop helps add to the fact that she is looking out to the left of the camera. However, it looks as though something like NeatImage has been used, since it feels like the detail in the hair has been lost.', '2002-12-11 13:55:12.000000', NULL, 1),
(170326, 9494, 749, '<td valign="top">Nicely composed shot, with plenty of interesting details. However, it all feels very grey, as if it had been converted to b&amp;w without any adjustments. This may be due to your monitor calibration being too dark (check by using the calibration greyscale at the bottom of all photos - you should be able to see the borders between all the blocks), but if not, it''d be worth making the whole image a bit darker and playing with the levels, to add some depth to the blacks if possible.</td>', 'Nicely composed shot, with plenty of interesting details. However, it all feels very grey, as if it had been converted to b&w without any adjustments. This may be due to your monitor calibration being too dark (check by using the calibration greyscale at the bottom of all photos - you should be able to see the borders between all the blocks), but if not, it''d be worth making the whole image a bit darker and playing with the levels, to add some depth to the blacks if possible.', '2002-12-11 14:02:04.000000', NULL, 1),
(170329, 9388, 749, '<td valign="top">Very creative idea this! I''m curious as to how you lit this, since the four corners of the shot are very yellowed, yet the centre has dark depths.</td>', 'Very creative idea this! I''m curious as to how you lit this, since the four corners of the shot are very yellowed, yet the centre has dark depths.', '2002-12-11 14:05:44.000000', NULL, 1),
(170337, 9583, 749, '<td valign="top">Hmm, yes, very abstract, but to the extent that there aren''t any main focal points :o/ However, the lines of the glass against the background are good, leading down from the upper corners into the centre., and the colours are very rich and vibrant. <br/> <br/>One final thing - the border isn''t very even, with the righthand side being wider than the lefthand, and it looks like a filter of some sort was applied after the border was created, as there is a noticable ghosting of it into the main image. Also, since the main background of the image is blue, perhaps a black border would help make it stand out a bit more.</td>', 'Hmm, yes, very abstract, but to the extent that there aren''t any main focal points :o/ However, the lines of the glass against the background are good, leading down from the upper corners into the centre., and the colours are very rich and vibrant.  One final thing - the border isn''t very even, with the righthand side being wider than the lefthand, and it looks like a filter of some sort was applied after the border was created, as there is a noticable ghosting of it into the main image. Also, since the main background of the image is blue, perhaps a black border would help make it stand out a bit more.', '2002-12-11 14:24:21.000000', NULL, 1),
(170340, 9447, 749, '<td valign="top">This is one of a couple of images this week that are too bright, probably due to monitor calibration (using the greyscale below each photo, set the monitor brightness so that the borders between each block are clearly visible). Otherwise, this is a good portrait shot; well lit and nicely focused.</td>', 'This is one of a couple of images this week that are too bright, probably due to monitor calibration (using the greyscale below each photo, set the monitor brightness so that the borders between each block are clearly visible). Otherwise, this is a good portrait shot; well lit and nicely focused.', '2002-12-11 14:29:17.000000', NULL, 1),
(170341, 9367, 749, '<td valign="top">Superb photo - very unusual perspective, and good use of the RoT. However, given the concentric ring patterns of this structure, a centred shot might also work well in this case.</td>', 'Superb photo - very unusual perspective, and good use of the RoT. However, given the concentric ring patterns of this structure, a centred shot might also work well in this case.', '2002-12-11 14:31:20.000000', NULL, 1),
(170343, 9550, 2302, '<td valign="top">Did you do all that yourself? This shot is just a bit too dark for my tastes but the focus and detail are great. I like the different patterns on the seeds and the overall pattern created by the rows. Nice = 7</td>', 'Did you do all that yourself? This shot is just a bit too dark for my tastes but the focus and detail are great. I like the different patterns on the seeds and the overall pattern created by the rows. Nice = 7', '2002-12-11 14:34:36.000000', NULL, 1),
(170347, 9402, 749, '<td valign="top">Very novel use of tree lights- did they get hot? :o) I''m not too sure about the green tone to the shot myself, as it means the green lights don''t contrast as much as they could have done - however, it really makes the red lights stand out. Unfortunately, both of the yellow lights are blown out, losing some of the detail there. Overall, I like the composition of  this shot, and the idea behind it is good.</td>', 'Very novel use of tree lights- did they get hot? :o) I''m not too sure about the green tone to the shot myself, as it means the green lights don''t contrast as much as they could have done - however, it really makes the red lights stand out. Unfortunately, both of the yellow lights are blown out, losing some of the detail there. Overall, I like the composition of  this shot, and the idea behind it is good.', '2002-12-11 14:37:08.000000', NULL, 1),
(170348, 9298, 2302, '<td valign="top">I like the framing of the structure on the left and the perspective it gives to the photo. The The sun spot makes what is otherwise a very soft picture rather harsh though.  = 6</td>', 'I like the framing of the structure on the left and the perspective it gives to the photo. The The sun spot makes what is otherwise a very soft picture rather harsh though.  = 6', '2002-12-11 14:38:03.000000', NULL, 1),
(170349, 9585, 2302, '<td valign="top">Nice colors on this. The lighting on the nose is too bad - looks a bit harsh. I like the shadows around the eye from the hair and how the details are shown so well. = 7</td>', 'Nice colors on this. The lighting on the nose is too bad - looks a bit harsh. I like the shadows around the eye from the hair and how the details are shown so well. = 7', '2002-12-11 14:41:46.000000', NULL, 1),
(170350, 9449, 749, '<td valign="top">I feel that this shot needs to be rotated clockwise by a few degrees, since the uprights of the roadsigns and buildings in the background distract by being not quite vertical. The subject matter of the shot is good, but perhaps a different shooting position (eg a bit more to the left) would have got you a more interesting composition.</td>', 'I feel that this shot needs to be rotated clockwise by a few degrees, since the uprights of the roadsigns and buildings in the background distract by being not quite vertical. The subject matter of the shot is good, but perhaps a different shooting position (eg a bit more to the left) would have got you a more interesting composition.', '2002-12-11 14:42:16.000000', NULL, 1),
(170352, 9417, 2302, '<td valign="top">That is just so cute. The only thing that would make it better would be if that was a blue bow around the next instead of the collar. Great detail and use of the border to really accent this shot. = 8</td>', 'That is just so cute. The only thing that would make it better would be if that was a blue bow around the next instead of the collar. Great detail and use of the border to really accent this shot. = 8', '2002-12-11 14:42:57.000000', NULL, 1),
(170353, 9551, 749, '<td valign="top">At first glance, this appeared to be an oddly slatted walkway, but then I worked out that it was a vertical shot :o) The perspective on this shot is simply superb. I''d be curious to see what this shot looks like either as a b&amp;w, or more saturated.</td>', 'At first glance, this appeared to be an oddly slatted walkway, but then I worked out that it was a vertical shot :o) The perspective on this shot is simply superb. I''d be curious to see what this shot looks like either as a b&w, or more saturated.', '2002-12-11 14:45:15.000000', NULL, 1),
(170355, 9559, 2302, '<td valign="top">I like the patterns created by the stucture. The picture looks as though there is a lot of noise in it and the details are not very strong. I get this kind of look when I use the digital telephoto on my camera. The background is a bit too stark for my taste - perhaps an adjustment of the brightness/contrast to make it a bit softer would help. = 5</td>', 'I like the patterns created by the stucture. The picture looks as though there is a lot of noise in it and the details are not very strong. I get this kind of look when I use the digital telephoto on my camera. The background is a bit too stark for my taste - perhaps an adjustment of the brightness/contrast to make it a bit softer would help. = 5', '2002-12-11 14:47:13.000000', NULL, 1),
(170356, 9469, 2302, '<td valign="top">It is interesting to see all the patterns and lines here. I like the branches show in the upper right and left of the shot. The only thing that bothers me is the rail on the left side being slightly blurred. The other parts of the shot look good though and the detail is nice. = 7</td>', 'It is interesting to see all the patterns and lines here. I like the branches show in the upper right and left of the shot. The only thing that bothers me is the rail on the left side being slightly blurred. The other parts of the shot look good though and the detail is nice. = 7', '2002-12-11 14:49:19.000000', NULL, 1),
(170357, 9553, 2302, '<td valign="top">Is it possible the background here is too white? It actually hurts me eyes to look at it a long time lol.  I think this is a nice shot - the detail on the foil is very good. Cute idea = 7</td>', 'Is it possible the background here is too white? It actually hurts me eyes to look at it a long time lol.  I think this is a nice shot - the detail on the foil is very good. Cute idea = 7', '2002-12-11 14:50:50.000000', NULL, 1),
(170360, 9312, 749, '<td valign="top">This is a simple, yet very effective illusion - it took me a few seconds to work it out when I first saw it. The colours seem a bit muted, especially those of the coat hangers, but I''d be curious to see whether converting to b&amp;w would help it. Oh, and good utilisation of the new aspect ratio rules :o)</td>', 'This is a simple, yet very effective illusion - it took me a few seconds to work it out when I first saw it. The colours seem a bit muted, especially those of the coat hangers, but I''d be curious to see whether converting to b&w would help it. Oh, and good utilisation of the new aspect ratio rules :o)', '2002-12-11 14:55:11.000000', NULL, 1),
(170361, 9473, 749, '<td valign="top">The colours in this shot are indeed very rich and Christmas-y, but there doesn''t seem to be any main focal points, so I''m not really sure what the main subject of the shot it. The lighting picks up some of the surface details of the purple and blue fabrics, yet there are very few details in the red or white, which is a shame. I''m not quite sure what the background is, so Iit might have helped to crop it out more, or to shoot from a different angle.</td>', 'The colours in this shot are indeed very rich and Christmas-y, but there doesn''t seem to be any main focal points, so I''m not really sure what the main subject of the shot it. The lighting picks up some of the surface details of the purple and blue fabrics, yet there are very few details in the red or white, which is a shame. I''m not quite sure what the background is, so Iit might have helped to crop it out more, or to shoot from a different angle.', '2002-12-11 14:59:37.000000', NULL, 1),
(170362, 9436, 749, '<td valign="top">Great head-on shot, and the DoF on it is good. However, it feels like the shot has been over-sharpened, and that some of the detail has been lost because of it.</td>', 'Great head-on shot, and the DoF on it is good. However, it feels like the shot has been over-sharpened, and that some of the detail has been lost because of it.', '2002-12-11 15:02:05.000000', NULL, 1),
(170363, 9558, 749, '<td valign="top">I can only assume that this was taken with a very low MPixel camera, as it is incredibly grainy, to the point where there are absolutely no details. Perhaps using one lens of a pair of binoculars would have helped zoom in and get more details.<br/> <br/>Oh, if you used digital zoom to get this, I recommend against using that feature, as you get lower quality and less control compared to cropping a shot yourself afterwards.</td>', 'I can only assume that this was taken with a very low MPixel camera, as it is incredibly grainy, to the point where there are absolutely no details. Perhaps using one lens of a pair of binoculars would have helped zoom in and get more details. Oh, if you used digital zoom to get this, I recommend against using that feature, as you get lower quality and less control compared to cropping a shot yourself afterwards.', '2002-12-11 15:05:12.000000', NULL, 1),
(170364, 9571, 749, '<td valign="top">Gah it looks like my original comment on this photo has disappeared, so I''ll try again - the composition and colours of this shot are good, creating plenty of interest within the shot. However, the lighting is too bright (some of the white leaves are almost blown out), and there isn''t enough contrast to bring out the surface details of most of the leaves, which is a shame. If this image doesn''t seem too bright, it may be due to your monitor calibration - please PM me if you want me to explain this further.</td>', 'Gah it looks like my original comment on this photo has disappeared, so I''ll try again - the composition and colours of this shot are good, creating plenty of interest within the shot. However, the lighting is too bright (some of the white leaves are almost blown out), and there isn''t enough contrast to bring out the surface details of most of the leaves, which is a shame. If this image doesn''t seem too bright, it may be due to your monitor calibration - please PM me if you want me to explain this further.', '2002-12-11 15:08:26.000000', NULL, 1),
(170366, 9567, 749, '<td valign="top">Very nice colours in this shot, which contrast well against the dark silhouettes of the trees. However, there appears to be a redish glow to the bottom edge of the photo, perhaps residual from a lens flare, which could be removed by recropping.</td>', 'Very nice colours in this shot, which contrast well against the dark silhouettes of the trees. However, there appears to be a redish glow to the bottom edge of the photo, perhaps residual from a lens flare, which could be removed by recropping.', '2002-12-11 15:10:40.000000', NULL, 1),
(170367, 9501, 749, '<td valign="top">Nice composition, and the sun shining through the leaves really helps add detail to them. However, since the DoF means that there is no other focal point, maybe a tighter crop would help.</td>', 'Nice composition, and the sun shining through the leaves really helps add detail to them. However, since the DoF means that there is no other focal point, maybe a tighter crop would help.', '2002-12-11 15:12:15.000000', NULL, 1),
(170368, 9503, 749, '<td valign="top">Good use of b&amp;w and the RoT here, and the dust on the seat really adds to the sense of disuse. However, the shot feels slightly tilted, and may benefit from being rotated clockwise by a few degrees.</td>', 'Good use of b&w and the RoT here, and the dust on the seat really adds to the sense of disuse. However, the shot feels slightly tilted, and may benefit from being rotated clockwise by a few degrees.', '2002-12-11 15:13:49.000000', NULL, 1),
(170370, 9452, 749, '<td valign="top">Odd, for some reason my comment for another photo was attached to this one, so my apologies if you were confused :o) This shot is well lit, but perhaps a bit too bright, maybe do to your monitor calibration (PM me if you want this explained more). The reflection off the surface helps add to this shot, but otherwise I cant find anything in this shot to interest me, sorry.</td>', 'Odd, for some reason my comment for another photo was attached to this one, so my apologies if you were confused :o) This shot is well lit, but perhaps a bit too bright, maybe do to your monitor calibration (PM me if you want this explained more). The reflection off the surface helps add to this shot, but otherwise I cant find anything in this shot to interest me, sorry.', '2002-12-11 15:18:48.000000', NULL, 1),
(170384, 9482, 1540, '<td valign="top">absoluterly beautiful</td>', 'absoluterly beautiful', '2002-12-11 15:47:00.000000', NULL, 1),
(170393, 9310, 772, '<td valign="top">nice portrait :)  Maybe a little smoother background would be nice as well... good shot :) - setzler</td>', 'nice portrait :)  Maybe a little smoother background would be nice as well... good shot :) - setzler', '2002-12-11 16:01:25.000000', NULL, 1),
(170394, 9558, 2302, '<td valign="top">I think having a different position of the moon within your photo would have helped here. Perhaps changing to a vertical shot with the moon high in the frame? = 5</td>', 'I think having a different position of the moon within your photo would have helped here. Perhaps changing to a vertical shot with the moon high in the frame? = 5', '2002-12-11 16:01:43.000000', NULL, 1),
(170395, 9494, 772, '<td valign="top">very interesting black and white shot... I love the scene here.. the lighting is maybe a tad bright from the sun.. maybe a ND filter or a polarizer would help some here... maybe that would also create a little stronger contrast... good shot :) - setzler</td>', 'very interesting black and white shot... I love the scene here.. the lighting is maybe a tad bright from the sun.. maybe a ND filter or a polarizer would help some here... maybe that would also create a little stronger contrast... good shot :) - setzler', '2002-12-11 16:03:49.000000', NULL, 1),
(170396, 9522, 2302, '<td valign="top">Interesting find. I only wish that the left side of the top piece was not cut out of the shot or that the shot was cropped so that you could only see the trees though the hole that is formed and not around the sides. Otherwise nice detail - good exposure on the snow. = 8</td>', 'Interesting find. I only wish that the left side of the top piece was not cut out of the shot or that the shot was cropped so that you could only see the trees though the hole that is formed and not around the sides. Otherwise nice detail - good exposure on the snow. = 8', '2002-12-11 16:04:47.000000', NULL, 1),
(170405, 9447, 2302, '<td valign="top">I like the position of this portrait. The only distraction for me is the tiny glare over the right eyebrow. I like the soft look of this without the focus being too soft. Overall nice lighting. = 7</td>', 'I like the position of this portrait. The only distraction for me is the tiny glare over the right eyebrow. I like the soft look of this without the focus being too soft. Overall nice lighting. = 7', '2002-12-11 16:24:01.000000', NULL, 1),
(170409, 9313, 2302, '<td valign="top">The only recommendation I would have is to see if you could adjust the lighting to eliminate the shadow from the white side. Otherwise I really like the contrasts in this picture. = 8</td>', 'The only recommendation I would have is to see if you could adjust the lighting to eliminate the shadow from the white side. Otherwise I really like the contrasts in this picture. = 8', '2002-12-11 16:27:41.000000', NULL, 1),
(170411, 9546, 4967, '<td valign="top">Good choice of making this black and white, very dramatic and lovely!  I love the sky... Really nice photo... I only wish the stuff aroundd the tree was a little more interesting.  Nice job though! -8</td>', 'Good choice of making this black and white, very dramatic and lovely!  I love the sky... Really nice photo... I only wish the stuff aroundd the tree was a little more interesting.  Nice job though! -8', '2002-12-11 16:33:02.000000', NULL, 1),
(170412, 9583, 4967, '<td valign="top">Very interstin picture here!  I love th blue background and the bright colors of the martini.  Very modern looking.  Nice job!  - 8</td>', 'Very interstin picture here!  I love th blue background and the bright colors of the martini.  Very modern looking.  Nice job!  - 8', '2002-12-11 16:34:19.000000', NULL, 1),
(170413, 9379, 2302, '<td valign="top">I really like the relection of the trees in the memorial and the trees that can be seen in the background. The wreath doesn''t really add much here (although I don''t suppose you could have moved it!) but I wish that the bottom part of the flowers was not cut off. = 7</td>', 'I really like the relection of the trees in the memorial and the trees that can be seen in the background. The wreath doesn''t really add much here (although I don''t suppose you could have moved it!) but I wish that the bottom part of the flowers was not cut off. = 7', '2002-12-11 16:35:39.000000', NULL, 1),
(170414, 9450, 4967, '<td valign="top">Very interesting perspective on this beautiful instrument.  Too bad about the hot spot bottom left and the reflection in the top right.  Great photo though!  - 8</td>', 'Very interesting perspective on this beautiful instrument.  Too bad about the hot spot bottom left and the reflection in the top right.  Great photo though!  - 8', '2002-12-11 16:37:15.000000', NULL, 1),
(170415, 9298, 4967, '<td valign="top">Personally I don''t think this photo has any real oomph.  I don''t really see fabulous colors, or a very striking scene... just a very bland sun with a building in front.  No offense or anything.  This could be improved with a different crop perhaps?  Maybe making it longer?  I''m really not sure.  Good try though.</td>', 'Personally I don''t think this photo has any real oomph.  I don''t really see fabulous colors, or a very striking scene... just a very bland sun with a building in front.  No offense or anything.  This could be improved with a different crop perhaps?  Maybe making it longer?  I''m really not sure.  Good try though.', '2002-12-11 16:49:22.000000', NULL, 1),
(170416, 9559, 4967, '<td valign="top">Interesting but extremely grainy... did you shoot this from the ground up, then crop it a whole bunch... The patterns are neat, but I don''t understand the title, because birds look down at things, not up.  good try.</td>', 'Interesting but extremely grainy... did you shoot this from the ground up, then crop it a whole bunch... The patterns are neat, but I don''t understand the title, because birds look down at things, not up.  good try.', '2002-12-11 16:50:39.000000', NULL, 1),
(170417, 9386, 4967, '<td valign="top">Nice picture of fire, but not extremely interesting... Good detail on the logs.  Would have liked it better maybe not so centered?</td>', 'Nice picture of fire, but not extremely interesting... Good detail on the logs.  Would have liked it better maybe not so centered?', '2002-12-11 16:56:25.000000', NULL, 1),
(170418, 9310, 4967, '<td valign="top">When taking portraits pay special attention to your background!  You have telephone wires coming out of his head, and a house growing out of his neck.  This is a rather boring shot... but the focus is excellent.</td>', 'When taking portraits pay special attention to your background!  You have telephone wires coming out of his head, and a house growing out of his neck.  This is a rather boring shot... but the focus is excellent.', '2002-12-11 16:58:45.000000', NULL, 1),
(170472, 9522, 4412, '<td valign="top">I little hot up front on the left I think you need some more contrast.</td>', 'I little hot up front on the left I think you need some more contrast.', '2002-12-11 19:27:19.000000', NULL, 1),
(170475, 9482, 4412, '<td valign="top">Very nice and colourful very greative.</td>', 'Very nice and colourful very greative.', '2002-12-11 19:31:32.000000', NULL, 1),
(170497, 9496, 772, '<td valign="top">Technically and compositionally, there is nothing wrong with this photo.  IMO, the background makes for a busy shot and your subject sign doesn''t really create a sense of high interest for me.  - Setzler</td>', 'Technically and compositionally, there is nothing wrong with this photo.  IMO, the background makes for a busy shot and your subject sign doesn''t really create a sense of high interest for me.  - Setzler', '2002-12-11 20:19:03.000000', NULL, 1),
(170520, 9491, 4162, '<td valign="top">This is a very charming portrait, obviously not camera shy! The lighting and background are perfect.  My only niggle, she seems to be holding onto the flowers for dear life, maybe just loosen up the hands a little.</td>', 'This is a very charming portrait, obviously not camera shy! The lighting and background are perfect.  My only niggle, she seems to be holding onto the flowers for dear life, maybe just loosen up the hands a little.', '2002-12-11 20:38:36.000000', NULL, 1),
(170525, 9367, 4162, '<td valign="top">What a unique picture! Great patterns and contrast.</td>', 'What a unique picture! Great patterns and contrast.', '2002-12-11 20:41:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(170527, 9388, 4162, '<td valign="top">Now that is macro spaghetti! Almost looks like a flower, quite a trippy image!</td>', 'Now that is macro spaghetti! Almost looks like a flower, quite a trippy image!', '2002-12-11 20:42:44.000000', NULL, 1),
(170529, 9585, 51167, '<td valign="top">Great angle and perspective.  The right side of the shot is a little bright.</td>', 'Great angle and perspective.  The right side of the shot is a little bright.', '2002-12-11 20:43:33.000000', NULL, 1),
(170530, 9469, 51167, '<td valign="top">neat view.  Still no snow here.  It looks a little tilted.</td>', 'neat view.  Still no snow here.  It looks a little tilted.', '2002-12-11 20:44:21.000000', NULL, 1),
