(5679313, 9482, 110831, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ArtistGary:</b></div><hr/><i> Remarkable!! What idiot could possibly have rated this a ''1'' out of 10? </i></td></tr></table> <br/> <br/>Well, it isn''t real obvious whether 1 or 10 is the highest rated score, now is it?  Perhaps they meant to score it a 10.  For a long time looking through other photos I wondered whether a 1 or 10 was the high score.  The problem comes from the fact that "we''re #1" makes sense and the fact that 1 is at the highest (on your computer screen) or "top" rated spot, which you would tend to think of as the highest mark from its position as well.  Why isn''t there an indication anywhere by the owners of this website of what''s high and low?  It should be made plainly obvious with a legend or key right beside all ratings, wherever they appear.</td>', 'Originally posted by ArtistGary: Remarkable!! What idiot could possibly have rated this a ''1'' out of 10?   Well, it isn''t real obvious whether 1 or 10 is the highest rated score, now is it?  Perhaps they meant to score it a 10.  For a long time looking through other photos I wondered whether a 1 or 10 was the high score.  The problem comes from the fact that "we''re #1" makes sense and the fact that 1 is at the highest (on your computer screen) or "top" rated spot, which you would tend to think of as the highest mark from its position as well.  Why isn''t there an indication anywhere by the owners of this website of what''s high and low?  It should be made plainly obvious with a legend or key right beside all ratings, wherever they appear.', '2009-10-07 21:52:24.000000', NULL, 0),
(5736475, 9310, 83313, '<td valign="top">OH! You''re supposed to take it out of the package! The instructions didn''t say that.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=812902" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/83313/120/Copyrighted_Image_Reuse_Prohibited_812902.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/83313/120/Copyrighted_Image_Reuse_Prohibited_812902.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/83313/120/Copyrighted_Image_Reuse_Prohibited_812902.jpg"/></a></td>', 'OH! You''re supposed to take it out of the package! The instructions didn''t say that.', '2009-11-21 23:06:49.000000', NULL, 0),
(6159716, 9310, 69008, '<td valign="top">Photos like this one are what make family albums great to have. They are little adults before you even notice, then one more eye blink, and you are making albums of the grandkids.</td>', 'Photos like this one are what make family albums great to have. They are little adults before you even notice, then one more eye blink, and you are making albums of the grandkids.', '2010-09-12 13:24:53.000000', NULL, 0),
